import{_ as d,C as a,o,c as n,E as i,a2 as r}from"./chunks/framework.Cm6XCzck.js";const P=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.7","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.7","type":"implementation-case","domain":"TMPA","version":"I0.7","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i0.7.md","filePath":"zh/publications/implementation-case-i0.7.md","lastUpdated":1786282064000}'),s={name:"zh/publications/implementation-case-i0.7.md"};function l(c,t,p,h,g,u){const e=a("ArticleCover");return o(),n("div",null,[i(e,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"覆盖 TMPA Core S0.5 全部准则的 CodeFlowMu V1.4.1 锁定产品运行，并保留 WP-13 治理证据。",version:"I0.7",status:"S0.5 产品证据草稿 · 14/14 PASS",languageHref:"/en/publications/implementation-case-i0.7",languageLabel:"English"}),t[0]||(t[0]=r(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="tmpa-core-s0-5、fcop-3-2-4、codeflowmu-v1-4-1-与-wp-13" tabindex="-1">TMPA Core S0.5、FCoP 3.2.4、CodeFlowMu V1.4.1 与 WP-13 <a class="header-anchor" href="#tmpa-core-s0-5、fcop-3-2-4、codeflowmu-v1-4-1-与-wp-13" aria-label="Permalink to &quot;TMPA Core S0.5、FCoP 3.2.4、CodeFlowMu V1.4.1 与 WP-13&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> 草稿 I0.7<br><strong>状态：</strong> 作者制作的实施与案例报告<br><strong>规范目标：</strong> <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>受测产品：</strong> CodeFlowMu V1.4.1，Commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code><br><strong>证据采集：</strong> 2026-08-09，Asia/Shanghai<br><strong>正式证据包：</strong> <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip</code><br><strong>压缩包 SHA-256：</strong> <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code><br><strong>权威边界：</strong> 本报告属于证据性、非规范性文档；只有 Core Specification 定义 TMPA 要求。</p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>I0.7 使用公开、Commit 锁定的 CodeFlowMu V1.4.1 源码，执行 TMPA Core S0.5 的全部十四项强制符合性准则。固定源码与测试 Bundle 下，产品矩阵为 <strong>14 PASS、0 PARTIAL、0 NOT RUN、0 FAIL</strong>。外部产品夹具通过 15/15 项断言；CodeFlowMu 内置 TMPA 套件通过 19/19；Runtime 为 1,446 passed / 0 failed / 1 skipped；Shell 为 775/775；FCoP 为 1,210 passed / 2 skipped；Protocol 与各项 Typecheck 均成功退出。</p><p>该结果升级了 I0.6 本地基线及保留的 CodeFlowMu V1.4.0 修复前基线。V1.4.0 为 12 PASS / 2 FAIL：C06 未能把生命周期完成与独立验收分开，C12 允许未授权裁决清除复核冲突。V1.4.1 修复这两个边界，同时没有弱化 C03 或 C10。V1.4.0 压缩包仅作为历史证据保留，不属于 I0.7 正式出版主包。</p><p>当前最强、且不越界的结论是：<strong>固定 Bundle 下由作者本地 demonstrated 的产品符合性</strong>。它不是独立认证、独立采用、任意输入上的形式证明，也不证明多智能体幻觉已被消除。WP-13 仍是独立的有限案例，只演示对最初未核验完成声明的证据门禁与角色分离复核。</p><h1 id="_1-范围与研究问题" tabindex="-1">1. 范围与研究问题 <a class="header-anchor" href="#_1-范围与研究问题" aria-label="Permalink to &quot;1. 范围与研究问题&quot;">​</a></h1><p>I0.7 回答以下问题：</p><ol><li>锁定的 CodeFlowMu V1.4.1 产品运行是否逐项满足 S0.5 的 C01–C14？</li><li>V1.4.1 是否在不混并其他治理准则的条件下关闭 V1.4.0 的两项失败？</li><li>如何表述 TMPA、FCoP、CodeFlowMu 与 WP-13，避免混淆理论、协议、应用与案例证据？</li><li>在结果可称为独立验证或独立采用之前，还存在哪些边界？</li></ol><p>裁决单位是固定源码与证据 Bundle 上、绑定具体准则的主张。四个成熟度层级严格分开：</p><table tabindex="0"><thead><tr><th>层级</th><th>I0.7 中的含义</th><th style="text-align:right;">是否达到</th></tr></thead><tbody><tr><td>Specified</td><td>由 TMPA Core S0.5 规范定义</td><td style="text-align:right;">是</td></tr><tr><td>Implemented</td><td>产品中存在相应机制</td><td style="text-align:right;">是</td></tr><tr><td>Demonstrated</td><td>作者运行产生了可检查证据</td><td style="text-align:right;">是，仅限本 Bundle 的 C01–C14</td></tr><tr><td>Independently Adopted</td><td>独立组织采用并验证该机制</td><td style="text-align:right;">否</td></tr></tbody></table><h1 id="_2-架构与证据边界" tabindex="-1">2. 架构与证据边界 <a class="header-anchor" href="#_2-架构与证据边界" aria-label="Permalink to &quot;2. 架构与证据边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ 理论与治理模型</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>        ↓ 规范对象、Reader 与符合性契约</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>        ↓ 基于文件的协同 Profile 与参考实现</span></span>
<span class="line"><span>CodeFlowMu 应用</span></span>
<span class="line"><span>        ↓ Runtime、角色、工作流、恢复与审计行为</span></span>
<span class="line"><span>WP-13 有限现场案例</span></span></code></pre></div><p>TMPA 是架构与治理理论。FCoP 是可复用的基于文件的协同协议，不是应用程序，也不是某个安装包主张；<code>fcop</code> 与 <code>fcop-mcp</code> 是该协议的参考实现。CodeFlowMu 是本次评估的下游应用。WP-13 是该工程谱系中的一个有限工作流案例，不能替代完整的 C01–C14 产品运行。</p><p>概念依赖与历史形成过程保持分离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>概念关系：TMPA → FCoP → CodeFlowMu / 其他应用</span></span>
<span class="line"><span>历史关系：小典实践 → 早期 TMPA → FCoP 提取</span></span>
<span class="line"><span>                               → CodeFlowMu → 当前 TMPA 形式化</span></span></code></pre></div><p>小典 AI 仍属于工程谱系和候选现场证据来源。I0.7 不增加小典符合性主张，因为本次没有执行固定的小典 S0.5 Bundle。</p><h1 id="_3-锁定来源与证据设计" tabindex="-1">3. 锁定来源与证据设计 <a class="header-anchor" href="#_3-锁定来源与证据设计" aria-label="Permalink to &quot;3. 锁定来源与证据设计&quot;">​</a></h1><table tabindex="0"><thead><tr><th>来源</th><th>锁定标识</th><th>I0.7 中的作用</th><th>边界</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.5</td><td>C01–C14 规范目标</td><td>规范，不是产品证据</td></tr><tr><td>CodeFlowMu</td><td>V1.4.1，Commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code></td><td>受测产品</td><td>可公开获取；初始化前为干净 detached checkout</td></tr><tr><td>FCoP</td><td>3.2.4，Commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code></td><td>协议与参考基线</td><td>可公开获取的干净 checkout</td></tr><tr><td>外部夹具</td><td>15 项强制断言</td><td>产品级 C01–C14 评估</td><td>固定测试构造，不是任意输入证明</td></tr><tr><td>WP-13 V3</td><td>已出版证据包</td><td>多 Agent 证据门禁案例</td><td>独立的作者制作案例证据</td></tr></tbody></table><p>原 CodeFlowMu 与 FCoP 本地工作树存在未提交内容，但证据采集未修改它们；测试使用固定的 detached checkout。CodeFlowMu 在产品初始化前是干净的，初始化生成文件另行记录于 <code>manifests/codeflowmu-post-initialization-status.txt</code>。证据采集期间没有 Push、Release 或 Tag。</p><p>正式公开包只包括 V1.4.1 ZIP 与外部 SHA-256 文件。V1.4.0 包记录 12 PASS / 2 FAIL 的修复前状态，仅作为历史证据保留；除非审稿人要求对照，否则不进入 I0.7 正式主包。</p><h1 id="_4-已执行测试基线" tabindex="-1">4. 已执行测试基线 <a class="header-anchor" href="#_4-已执行测试基线" aria-label="Permalink to &quot;4. 已执行测试基线&quot;">​</a></h1><p>全部主要运行均由作者在锁定源码上执行。跳过项不会被换算为通过项。</p><table tabindex="0"><thead><tr><th>轨道</th><th style="text-align:right;">结果</th><th style="text-align:right;">Exit</th><th>解释</th></tr></thead><tbody><tr><td>外部 S0.5 产品夹具</td><td style="text-align:right;">15/15 断言</td><td style="text-align:right;">0</td><td>C01–C14 强制产品级 Bundle</td></tr><tr><td>CodeFlowMu 内置 TMPA 套件</td><td style="text-align:right;">19/19 测试</td><td style="text-align:right;">0</td><td>产品准则映射回归</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">通过</td><td style="text-align:right;">0</td><td>协议测试，与符合性裁决分开</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,446 passed、0 failed、1 skipped</td><td style="text-align:right;">0</td><td>锁定的完整 Runtime 运行</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">775/775</td><td style="text-align:right;">0</td><td>初始化后的隔离产品实例</td></tr><tr><td>Protocol / Runtime / Shell Typecheck</td><td style="text-align:right;">全部通过</td><td style="text-align:right;">0</td><td>仅静态检查</td></tr><tr><td>FCoP 3.2.4 源码基线</td><td style="text-align:right;">1,210 passed、2 skipped</td><td style="text-align:right;">0</td><td>迁移布局下两个历史样例跳过</td></tr></tbody></table><p>准则聚合结果为 <strong>14 PASS / 0 PARTIAL / 0 NOT RUN / 0 FAIL</strong>。这是固定 I0.7 Bundle 的产品结果，不是从 Reference Reader 继承的结果，也不是覆盖所有部署的普遍定理。</p><h1 id="_5-c01–c14-产品结果" tabindex="-1">5. C01–C14 产品结果 <a class="header-anchor" href="#_5-c01–c14-产品结果" aria-label="Permalink to &quot;5. C01–C14 产品结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.5 准则</th><th style="text-align:right;">裁决</th><th>执行观察</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证</td><td style="text-align:right;"><strong>PASS</strong></td><td>九类强制错误 Schema 均产生 <code>SCHEMA_INVALID</code>，且没有形成权威节点。</td></tr><tr><td>C02</td><td>主载体与不可变性</td><td style="text-align:right;"><strong>PASS</strong></td><td>内容寻址修订与可归责 <code>CORRECTION</code> 证据保持完整；<code>parent</code> 通过 FCoP Markdown 投影和 Reader 重建。</td></tr><tr><td>C03</td><td>重复身份</td><td style="text-align:right;"><strong>PASS</strong></td><td>同 ID 异内容候选均被保留，无候选获胜，并产生确定性的关键冲突隔离。</td></tr><tr><td>C04</td><td>流连续性与异步推进</td><td style="text-align:right;"><strong>PASS</strong></td><td>重号、缺口被报告；无关流继续重建；没有虚构缺失对象；到达顺序不改变输出。</td></tr><tr><td>C05</td><td>角色权威</td><td style="text-align:right;"><strong>PASS</strong></td><td>权限拒绝与权限不确定分支均产生要求的问题，且不改变重建状态。</td></tr><tr><td>C06</td><td>生命周期合法性</td><td style="text-align:right;"><strong>PASS</strong></td><td>缺少独立验收时 <code>work_state</code> 保持 <code>review</code>，并同时产生 <code>LIFECYCLE_UNDETERMINED</code> 与 <code>ACCEPTANCE_UNDETERMINED</code>；非法及冲突状态分支也匹配。</td></tr><tr><td>C07</td><td>职责分离与人工控制</td><td style="text-align:right;"><strong>PASS</strong></td><td>同一身份使用不同角色标签被拒绝；高风险工作在 ADMIN 批准证据前保持 <code>pending_human</code>。</td></tr><tr><td>C08</td><td>完整性篡改</td><td style="text-align:right;"><strong>PASS</strong></td><td>被覆盖内容修改产生 <code>INTEGRITY_MISMATCH</code>；对象被排除出权威节点，同时失败来源仍保留在 Manifest。</td></tr><tr><td>C09</td><td>缺失引用</td><td style="text-align:right;"><strong>PASS</strong></td><td><code>MISSING_REFERENCE</code> 与 <code>CLAIM_EVIDENCE_MISSING</code> 持续可见；依赖与完成主张均未被视为满足。</td></tr><tr><td>C10</td><td>禁止引用环</td><td style="text-align:right;"><strong>PASS</strong></td><td>只隔离禁止环成员，无关有效节点仍保持权威。</td></tr><tr><td>C11</td><td>确定性重建</td><td style="text-align:right;"><strong>PASS</strong></td><td>固定四来源的 24 种排列产生字节等价的规范结果，SHA-256 为 <code>84e22cf795301ef0eaeaaa026154bfbef3d8cb94a49d3445484443fceaf0c85e</code>。</td></tr><tr><td>C12</td><td>冲突保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>矛盾复核保持 <code>disputed</code>；未授权 DEV 裁决作为证据保留但不能清除冲突；具有 <code>resolve_review_conflict</code> 权限的已分配 PM 可以解决。</td></tr><tr><td>C13</td><td>恢复</td><td style="text-align:right;"><strong>PASS</strong></td><td>全新 Reader 对生命周期、责任、未解决依赖、失败/恢复、父子状态和 <code>CHILD_WORK_OPEN</code> 的重建一致。</td></tr><tr><td>C14</td><td>终态历史保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>只有已验收、已授权的链进入 archive；任务、报告、复核、验收与状态转换历史均可重建。</td></tr></tbody></table><h1 id="_6-v1-4-0-→-v1-4-1-修复分析" tabindex="-1">6. V1.4.0 → V1.4.1 修复分析 <a class="header-anchor" href="#_6-v1-4-0-→-v1-4-1-修复分析" aria-label="Permalink to &quot;6. V1.4.0 → V1.4.1 修复分析&quot;">​</a></h1><p>修复对照严格限定范围。V1.4.0 已经通过 C02 与 C07；当时失败的是 C06 与 C12。</p><h2 id="_6-1-c06——生命周期不等于验收" tabindex="-1">6.1 C06——生命周期不等于验收 <a class="header-anchor" href="#_6-1-c06——生命周期不等于验收" aria-label="Permalink to &quot;6.1 C06——生命周期不等于验收&quot;">​</a></h2><p>V1.4.0 在生命周期证据看似充分、但缺少独立验收时仍允许 <code>review → done</code>，从而把流程推进与业务验收混为一体。V1.4.1 分别计算两类判断：没有独立验收，工作保持 <code>review</code>，同时输出生命周期与验收不确定。产品不再从不完整权威链中制造“完成”。</p><h2 id="_6-2-c12——只有授权解决者可以清除冲突" tabindex="-1">6.2 C12——只有授权解决者可以清除冲突 <a class="header-anchor" href="#_6-2-c12——只有授权解决者可以清除冲突" aria-label="Permalink to &quot;6.2 C12——只有授权解决者可以清除冲突&quot;">​</a></h2><p>V1.4.0 能保留矛盾复核，但允许后续未授权裁决清除争议。V1.4.1 保留未授权 DEV 裁决作为证据，产生权限问题，并让 <code>UNRESOLVED_CONFLICT</code> 继续有效。只有来自已分配、具有 <code>resolve_review_conflict</code> 权限的角色的裁决对象——本次以 PM 演示——才能解决冲突。</p><h2 id="_6-3-回归边界" tabindex="-1">6.3 回归边界 <a class="header-anchor" href="#_6-3-回归边界" aria-label="Permalink to &quot;6.3 回归边界&quot;">​</a></h2><p>C03 继续负责同 ID 异内容的候选冲突；C10 继续负责禁止引用环。两者都没有被并入 C12，且回归继续通过。若补丁通过弱化或重定义相邻准则来取得成功，就不能构成 S0.5 demonstrated 证据。</p><h1 id="_7-wp-13-多-agent-证据门禁案例" tabindex="-1">7. WP-13 多 Agent 证据门禁案例 <a class="header-anchor" href="#_7-wp-13-多-agent-证据门禁案例" aria-label="Permalink to &quot;7. WP-13 多 Agent 证据门禁案例&quot;">​</a></h1><p>WP-13 回答的问题不同于 C01–C14 Bundle：角色分离的工作流能否阻止未经核验的完成声明成为权威交付事实？</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>带完成含义的声明</span></span>
<span class="line"><span>        ↓ 持久证据不完整</span></span>
<span class="line"><span>PM 事实核验 → 暂停 / 不发布 / 不派 QA</span></span>
<span class="line"><span>        ↓ 同任务恢复</span></span>
<span class="line"><span>DEV Commit + Report</span></span>
<span class="line"><span>        ↓ 独立角色</span></span>
<span class="line"><span>QA 复跑与报告</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>授权 Gate C 裁决</span></span></code></pre></div><p>最初 DEV 子执行使用了带完成含义的语言，但退出状态、测试、Commit 与正式报告并未全部建立。PM 检查持久事实，暂停发布且未派 QA。恢复后，DEV 补齐证据，角色分离的 QA 重新执行测试与检查。后续 Gate C 记录完成业务验收；Active、Push/发布和 Archive 仍是分开的裁决。</p><p>该案例演示证据门禁、职责分离、同任务恢复与分阶段权威。它<strong>不证明</strong>模型不再产生幻觉，不保证所有错误声明都会被发现，也不表示原始 V3 快照已经包含终态批准。其快照边界记录 <code>runtime_bound: false</code>，TASK-019/020 仍为 <code>review / pending</code>；后续验收不得倒写为早期快照事实。</p><h1 id="_8-三值治理解释" tabindex="-1">8. 三值治理解释 <a class="header-anchor" href="#_8-三值治理解释" aria-label="Permalink to &quot;8. 三值治理解释&quot;">​</a></h1><p>TMPA 将语义判断与视图分类分开：</p><table tabindex="0"><thead><tr><th>判断</th><th>典型视图</th><th>含义</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>所需证据与适用规则能够建立结论。</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>确定性违规排除受影响的证据或动作。</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>证据缺失、冲突，或仍需授权人工裁决。</td></tr></tbody></table><p>这种区别在 I0.7 中可直接观察。C06 缺少验收并不表示工作为假，而是让完成保持不确定并阻止状态推进。C12 未授权裁决作为证据保留，但作为解决冲突的权威动作无效。C08 隔离被篡改的覆盖内容，同时在 Manifest 中保留失败来源。因此 Reader 既重建可用事实，也重建其他证据被排除或推迟的原因。</p><h1 id="_9-可复现性与证据质量" tabindex="-1">9. 可复现性与证据质量 <a class="header-anchor" href="#_9-可复现性与证据质量" aria-label="Permalink to &quot;9. 可复现性与证据质量&quot;">​</a></h1><p>正式 V1.4.1 压缩包包含 68 个文件，外部 SHA-256 为 <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code>。压缩包完整性、内部 Payload Manifest、严格 UTF-8 解码、JSON/JSONL 解析及内置验证脚本均通过。隐私扫描覆盖 65 个文本文件，未发现问题。</p><p>证据包保留：</p><ul><li>固定源码标识与 Checkout 状态；</li><li>依赖锁文件与环境元数据；</li><li>带 Exit Code 与耗时的精确命令；</li><li>原始 stdout/stderr 与结构化运行摘要；</li><li>包含 15 项断言的外部产品夹具；</li><li>C01–C14 矩阵与规范化 Actual 输出；</li><li>S0.5 投影与 Reader 的源码摘录；</li><li>内部 SHA-256 Manifest 与证据验证器。</li></ul><p>一个元数据限制被明确保留：采集器没有解析到可执行文件名，因此 <code>environment.json</code> 将 npm 记录为 unavailable；但运行记录明确通过 Windows 的 <code>npm.cmd</code> 执行，并保留了日志与 Exit Code。这限制了“已捕获 npm 版本”的主张，但不改变已执行测试的裁决。</p><h1 id="_10-限制" tabindex="-1">10. 限制 <a class="header-anchor" href="#_10-限制" aria-label="Permalink to &quot;10. 限制&quot;">​</a></h1><ol><li>结果由作者在固定 Commit 与固定 Bundle 上执行；尚无独立第三方复跑或认证。</li><li>Runtime 保留 1 项 skipped；FCoP 在迁移布局下保留 2 项历史样例 skipped。</li><li>Shell 使用产品原生初始化后的隔离实例；生成文件与源码 Commit 分开记录。</li><li>C08 演示治理对象完整性处理，不代表安装文件自保护、身份认证或事实真实性。</li><li>C11 覆盖固定四来源及其全部 24 种排列，不是任意来源数量或对抗环境下的形式证明。</li><li>本证据不支持代表性 SME 性能、比较优势、拜占庭韧性或第三方采用主张。</li><li>WP-13 是有限治理案例，不是幻觉消除基准。</li><li>证据采集本身没有创建论文发布、Push、Release 或 Tag；这些出版动作由仓库历史另行治理。</li></ol><h1 id="_11-主张台账" tabindex="-1">11. 主张台账 <a class="header-anchor" href="#_11-主张台账" aria-label="Permalink to &quot;11. 主张台账&quot;">​</a></h1><table tabindex="0"><thead><tr><th>主张</th><th>I0.7 处理</th></tr></thead><tbody><tr><td>TMPA Core S0.5 定义 C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.4.1 包含相应产品机制</td><td><strong>Implemented</strong></td></tr><tr><td>锁定的作者运行 Bundle 记录 14/14 产品 PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>结果已由独立第三方复跑或认证</td><td><strong>未演示</strong></td></tr><tr><td>TMPA 已被其他组织独立采用</td><td><strong>未演示</strong></td></tr><tr><td>WP-13 证明消除幻觉</td><td><strong>禁止结论</strong></td></tr></tbody></table><h1 id="_12-工程结论" tabindex="-1">12. 工程结论 <a class="header-anchor" href="#_12-工程结论" aria-label="Permalink to &quot;12. 工程结论&quot;">​</a></h1><p>I0.7 将实施案例从 I0.6 的混合本地产品基线，推进到干净、可公开获取的 CodeFlowMu V1.4.1 源码锁定与完整的产品级 C01–C14 执行。固定 Bundle 下正式结果为 14 PASS / 0 FAIL。V1.4.0 的两项失败，通过保持生命周期与验收分离、并要求授权冲突解决而关闭。</p><p>该结果之所以构成有效工程证据，是因为它保留了精确源码、命令、输出、逐项观察、限制与修复历史。其边界同样重要：它演示实现行为，但不证明 TMPA 理论，不认证所有 CodeFlowMu 部署，也不建立独立采用。FCoP 仍是协议层，CodeFlowMu 是应用层，WP-13 是有限治理案例。</p><h1 id="证据获取" tabindex="-1">证据获取 <a class="header-anchor" href="#证据获取" aria-label="Permalink to &quot;证据获取&quot;">​</a></h1><p>I0.7 正式证据包为 <a href="/joinwell52/evidence/tmpa/i0.7/tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip">tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip</a>。同目录文件 <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip.sha256</code> 记录 <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code>。</p><p>V1.4.0 的 12 PASS / 2 FAIL 压缩包作为修复前历史证据保留，但不作为 I0.7 正式主包发布。历史 I0.6 证据包与 WP-13 V3 继续保留在各自版本路径。Git History 是出版版本历史，不存在具有编辑权威的并行论文数据库。</p><h1 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.5.” GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.7.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” version 3.2.4, commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.4.1,” commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code>. GitHub, 2026.</p><p>[5] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3.” GitHub, 2026.</p><p>[6] TMPA Project. “I0.7 CodeFlowMu V1.4.1 Evidence,” package <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809</code>, 2026.</p>`,67))])}const b=d(s,[["render",l]]);export{P as __pageData,b as default};
